/**
 * Checks if the given timestamp is in the given time range.
 *
 * @param timestamp the timestamp to check
 * @param timeRanges the time ranges to check against
 * @return true if the timestamp is in the given time range, false otherwise
 */
private static boolean isInTimeRange(long timestamp, List<ProfileAnalyzeTimeRange> timeRanges) {
    for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
        if (timestamp >= timeRange.getStartTime() && timestamp <= timeRange.getEndTime()) {
            return true;
        }
    }
    return false;
}
